<?php
// Runs only within the disposable schema-cloning API harness.
$db->prepare("INSERT INTO tools(name,code,category,quantity,available) VALUES('Baso','ACCEPT-BASO','Test',30,30)")->execute();
$baso=(int)$db->lastInsertId();
$db->prepare("INSERT INTO borrowers(full_name,id_number,type) VALUES('Acceptance Borrower','ACCEPT-BORROWER','Guest')")->execute();$person=(int)$db->lastInsertId();
$checkout=['type'=>'borrow_batch','borrower_id'=>$person,'due_date'=>date('Y-m-d',strtotime('+1 day')),'due_time'=>'17:30','items'=>[['tool_code'=>'ACCEPT-BASO','qty'=>6]],'request_token'=>'accept_borrow_six_123456'];
$six=expectApi('Baso first loan six','transactions.php','POST',$checkout)['items'][0]['id'];
$checkout['items'][0]['qty']=9;$checkout['request_token']='accept_borrow_nine_12345';
$nine=expectApi('Baso separate loan nine','transactions.php','POST',$checkout)['items'][0]['id'];
$retry=expectApi('Checkout response lost then retried','transactions.php','POST',$checkout);
check($retry['duplicate']&&$retry['items'][0]['id']===$nine,'Checkout retry returns original loan line');
check((int)row('tools',$baso)['available']===15,'After both checkouts: owned 30, available 15, outstanding 15');
$bad=$checkout;$bad['items'][0]['qty']=1;expectApi('Token cannot change payload','transactions.php','POST',$bad,false);
$bad=$checkout;$bad['request_token']='accept_empty_list_123456';$bad['items']=[];expectApi('Empty cart','transactions.php','POST',$bad,false);
$bad['items']=[['tool_code'=>'ACCEPT-BASO','qty'=>16]];expectApi('Excessive checkout','transactions.php','POST',$bad,false);
$ret=['type'=>'return','borrow_txn_id'=>$nine,'returnee_name'=>'Test Staff','request_token'=>'accept_nine_damage_12345','items'=>['damaged'=>9]];
expectApi('Nine Baso returned damaged','transactions.php','POST',$ret,true,'Staff');expectApi('Return response retry','transactions.php','POST',$ret,true,'Staff');
check(row('transactions',$nine)['status']==='returned'&&(int)row('transactions',$six)['qty_returned']===0,'Only nine-unit loan closes; six-unit loan remains outstanding');
$cases=$db->query("SELECT * FROM replacement_requests WHERE tool_id=$baso")->fetchAll();$case=(int)$cases[0]['id'];
check(count($cases)===1&&(int)$cases[0]['incident_quantity']===9&&(int)row('tools',$baso)['available']===15,'Exactly one nine-unit case; availability unchanged');
$action=function(string $action,int $qty,string $token,bool $ok=true)use($case){return expectApi('Partial case '.$action,'replacement_requests.php','PATCH',['id'=>$case,'version'=>(int)row('replacement_requests',$case)['payment_version'],'action'=>'inventory_resolution','inventory_action'=>$action,'quantity'=>$qty,'notes'=>'Acceptance inspection','request_token'=>$token],$ok);};
$action('repair',3,'accept_repair_three_1234');
check((int)row('tools',$baso)['available']===15,'Under repair does not release stock');
$action('available',3,'accept_approve_three_123');
check((int)row('tools',$baso)['available']===18&&(int)row('replacement_requests',$case)['resolved_quantity']===3,'Approval adds exactly three; six remain unresolved');
$dispose=['action'=>'dispose_damaged','id'=>$baso,'quantity'=>1,'reason'=>'Beyond repair','case_id'=>$case,'case_version'=>(int)row('replacement_requests',$case)['payment_version'],'request_token'=>'accept_disposal_one_1234'];
expectApi('Tools case disposal uses shared case rules','tools.php','POST',$dispose);
$again=expectApi('Disposal retry','tools.php','POST',$dispose);check($again['duplicate'],'Disposal retry is idempotent');
$t=row('tools',$baso);$c=row('replacement_requests',$case);
check((int)$t['quantity']===29&&(int)$t['available']===18&&(int)$t['damaged_qty']===5&&(int)$c['resolved_quantity']===4&&(int)$c['incident_quantity']===9,'Final Baso: owned 29, available 18, on loan 6, damaged/unresolved 5; original incident nine');
$action('dispose',6,'accept_excess_dispose_123',false);
$report=expectApi('Historical return report','reports.php','GET',[],true,'Staff',['type'=>'returns']);
$ri=array_search('Damaged at Return',$report['columns'],true);$matches=array_values(array_filter($report['rows'],fn($r)=>$r[0]==='Baso'));
check(count($matches)===1&&(int)$matches[0][$ri]===9,'Report keeps nine damaged at return after repair and disposal');
$cmd=[PHP_BINARY,$work.'/worker.php','reports.php','GET','{}','Staff','type=returns&download=1'];
$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$csv=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);proc_close($p);
$csvRows=array_map('str_getcsv',explode("\n",trim($csv)));$csvBaso=array_values(array_filter($csvRows,fn($r)=>($r[0]??'')==='Baso'));
check(count($csvBaso)===1&&(int)$csvBaso[0][$ri]===9&&str_contains($csv,'Damaged at Return'),'CSV and report preserve identical historical condition totals');
$tools=expectApi('Tools final Baso balance','tools.php','GET',[],true,'Staff',['id'=>$baso]);
check((int)$tools['quantity']===29&&(int)$tools['available']===18&&(int)$tools['damaged_qty']===5,'Tools exposes reconciled final balance');
$loans=expectApi('Return final Baso loan lines','transactions.php','GET',[],true,'Staff',['type'=>'student_loans','borrower_id'=>$person]);
check(count($loans['loans'])===1&&(int)$loans['loans'][0]['id']===$six&&(int)$loans['loans'][0]['outstanding']===6,'Return displays only the original outstanding six-unit loan');
$db->prepare("UPDATE transactions SET due_date=CURDATE(),due_time='00:00:00' WHERE id=?")->execute([$six]);
$todayLoans=expectApi('Same-day actual due time','transactions.php','GET',[],true,'Staff',['type'=>'student_loans','borrower_id'=>$person]);
check((int)$todayLoans['loans'][0]['is_overdue']===1&&str_contains($todayLoans['loans'][0]['due_label'],'12:00 AM'),'Return identifies earlier-today overdue timestamp in application timezone');
$borrows=expectApi('Borrow final loan balances','transactions.php','GET',[],true,'Staff',['type'=>'borrow','search'=>'ACCEPT-BASO']);
check(count($borrows)===2&&array_sum(array_column($borrows,'outstanding'))===6,'Borrow history reconciles separate completed and outstanding loan lines');
$details=expectApi('Case details reconcile','replacement_requests.php','GET',[],true,'Staff',['details'=>$case]);
check((int)$details['request']['unresolved_quantity']===5&&count($details['events'])===4,'Case details and timeline preserve original and partial quantities');
$mixed=['type'=>'return','borrow_txn_id'=>$six,'returnee_name'=>'Test Staff','request_token'=>'accept_mixed_partial_123','items'=>['good'=>1,'minor'=>1,'damaged'=>1]];
expectApi('Mixed partial return on original six-unit line','transactions.php','POST',$mixed,true,'Staff');
check((int)row('transactions',$six)['qty_returned']===3&&row('transactions',$six)['status']==='active','Unprocessed units stay on original loan');
$mixed['request_token']='accept_excess_return_123';$mixed['items']=['good'=>4];expectApi('Combined return exceeds outstanding','transactions.php','POST',$mixed,false,'Staff');
// A forced database failure must roll back the token, loan and inventory together.
$db->exec("CREATE TRIGGER accept_fail BEFORE INSERT ON transactions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Acceptance failure'");
$checkout['request_token']='accept_failed_retry_1234';$checkout['items'][0]['qty']=1;
$before=row('tools',$baso);expectApi('Forced checkout failure','transactions.php','POST',$checkout,false);
$db->exec('DROP TRIGGER accept_fail');check(row('tools',$baso)===$before,'Failed checkout leaves all stock unchanged');
expectApi('Retry failed checkout with same token','transactions.php','POST',$checkout);
$db->exec("INSERT INTO tools(name,code,category,quantity,available) VALUES('Last unit','ACCEPT-LAST','Test',1,1)");
$checkout['items']=[['tool_code'=>'ACCEPT-LAST','qty'=>1]];$checkout['request_token']='accept_last_unit_A12345';$other=$checkout;$other['request_token']='accept_last_unit_B12345';
$race=concurrentApi('transactions.php','POST',[],2,[$checkout,$other]);check(count(array_filter($race,fn($r)=>$r['success']))===1,'Concurrent last-unit checkout admits exactly one loan');
$checkout['items']=[['tool_code'=>'ACCEPT-BASO','qty'=>1]];$checkout['request_token']='accept_concurrent_retry_123';
$twice=concurrentApi('transactions.php','POST',$checkout);
check(count(array_filter($twice,fn($r)=>$r['success']))===2&&$twice[0]['data']['items'][0]['id']===$twice[1]['data']['items'][0]['id'],'Concurrent identical checkout retries return one original loan');
// Old loans have no submission record and still return through their original numeric line ID.
$db->exec("INSERT INTO tools(name,code,category,quantity,available) VALUES('Legacy tool','ACCEPT-LEGACY','Test',2,0)");$legacyTool=(int)$db->lastInsertId();
$db->prepare("INSERT INTO transactions(txn_id,type,tool_id,borrower_id,status,qty,due_date,borrower_name_snapshot) VALUES('ACCEPT-OLD-LOAN','borrow',?,?,'active',2,CURDATE(),'Acceptance Borrower')")->execute([$legacyTool,$person]);$oldLoan=(int)$db->lastInsertId();
$db->prepare('UPDATE borrowers SET active_borrows=active_borrows+1,total_borrows=total_borrows+1 WHERE id=?')->execute([$person]);
expectApi('Loan predating submission tokens remains returnable','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$oldLoan,'returnee_name'=>'Staff','request_token'=>'accept_legacy_return_123','items'=>['good'=>2]],true,'Staff');
check((int)row('tools',$legacyTool)['available']===2&&row('transactions',$oldLoan)['status']==='returned','Legacy loan closes using unchanged original ID');
invariant();echo "PASSED: $checks cumulative inventory consistency checks\n";
